package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;
public final class WalletActivity extends Activity {
 private CommerceUi ui;private FrameLayout bodyHost;private JSONObject wallet;private boolean hidden,initialResume=true;private String filter="all";
 public void setContentView(View view){super.setContentView(CommerceChrome.wrap(this,view));}
 protected void attachBaseContext(Context c){super.attachBaseContext(I18n.localized(c));}
 public void onCreate(Bundle b){setTheme(getResources().getIdentifier(WebTheme.isDark(this)?"Kinnect.App.Dark":"Kinnect.App.Light","style",getPackageName()));super.onCreate(b);ui=new CommerceUi(this);getWindow().setStatusBarColor(ui.bg);getWindow().setNavigationBarColor(ui.bg);getWindow().getDecorView().setSystemUiVisibility(WebTheme.isDark(this)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);bodyHost=new FrameLayout(this);bodyHost.setBackgroundColor(ui.bg);setContentView(bodyHost);NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);load();}
 @Override protected void onResume(){super.onResume();CommerceChrome.refreshAccount(this);if(initialResume){initialResume=false;}else load();}
 private void setBody(View view){if(bodyHost==null){bodyHost=new FrameLayout(this);bodyHost.setBackgroundColor(ui.bg);setContentView(bodyHost);}bodyHost.removeAllViews();bodyHost.addView(view,new FrameLayout.LayoutParams(-1,-1));}
 private void showLoadError(){LinearLayout errPage=ui.col();errPage.setBackgroundColor(ui.bg);errPage.addView(header());errPage.addView(ui.empty("wallet","Chưa tải được ví"));errPage.addView(ui.action("Thử lại","refresh_cw",this::load));setBody(errPage);}
 private String number(long value){return java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(value);}
 private void load(){JSONObject cached=NativeApi.shared.cachedGet("/api/wallet");final String cachedSig=cached==null?"":cached.toString();if(cached!=null){draw(cached);}else{LinearLayout page=ui.col();page.setBackgroundColor(ui.bg);page.addView(header());page.addView(ui.empty("wallet","Đang tải…"));setBody(page);}NativeApi.shared.call("GET","/api/wallet",null,null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){if(wallet==null)showLoadError();return;}if(wallet==null||!data.toString().equals(cachedSig))draw(data);},()->{if(!isFinishing()&&!isDestroyed()&&wallet==null)showLoadError();});}
 private void info(){new Sheet(this).setTitle(I18n.t("Ví Kinnect")).setMessage(I18n.t("Xu tặng và quà nhận từ xu tặng không rút được. Xu mua còn dư được rút theo tỷ lệ quy đổi. Quà từ xu mua tạo thu nhập sau phí và hoàn tiền: người nhận 75%, nền tảng 25%. Không cộng trùng xu mua đã gửi quà. Nạp và rút tiền thật chưa mở.")).setPositiveButton(I18n.t("Đóng"),null).show();}
 private LinearLayout header(){LinearLayout line=ui.row();line.setPadding(ui.dp(10),ui.dp(8),ui.dp(12),ui.dp(8));int raw48=ui.dpRaw(48);FrameLayout back=ui.backButton(this::finish);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(raw48,raw48);bp.rightMargin=ui.dp(4);line.addView(back,bp);UiMetrics.enforceMinTouchTarget(back);TextView title=ui.text("Ví",18,ui.ink,true);line.addView(title,new LinearLayout.LayoutParams(0,-2,1));FrameLayout infoIcon=ui.icon("info","Thông tin ví",this::info);line.addView(infoIcon,new LinearLayout.LayoutParams(raw48,raw48));UiMetrics.enforceMinTouchTarget(infoIcon);FrameLayout refreshIcon=ui.icon("refresh_cw","Làm mới",this::load);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(raw48,raw48);rp.leftMargin=ui.dp(4);line.addView(refreshIcon,rp);UiMetrics.enforceMinTouchTarget(refreshIcon);return line;}
 private LinearLayout compactCard(){LinearLayout card=ui.section();card.setPadding(ui.dp(12),ui.dp(10),ui.dp(12),ui.dp(10));android.graphics.drawable.GradientDrawable bg=ui.round(ui.card,16);bg.setStroke(Math.max(1,ui.dp(1)),WebDesign.LINE[WebTheme.isDark(this)?1:0]);card.setBackground(bg);card.setElevation(0);return card;}
 private String entryCategory(JSONObject entry){String cat=entry.optString("category");if(!cat.isEmpty())return cat;String kind=entry.optString("kind");if(kind.equals("signup_trial")||kind.equals("admin_trial")||kind.equals("live_gift_received_trial"))return "grant";if(kind.equals("farm_trial"))return entry.optLong("coins")>=0?"grant":"spend";if(kind.equals("store_trial")||kind.equals("store_paid")||kind.equals("live_gift_trial")||kind.equals("live_gift_paid"))return "spend";if(kind.equals("coin_purchase"))return "topup";return "income";}
 private String entryIcon(String kind){if(kind.equals("signup_trial")||kind.equals("admin_trial")||kind.equals("farm_trial"))return "sparkles";if(kind.equals("store_trial")||kind.equals("store_paid"))return "store";if(kind.equals("coin_purchase"))return "plus";if(kind.equals("creator_settlement"))return "arrow_up_right";return "gift";}
 private void draw(JSONObject w){wallet=w;if(ui==null)ui=new CommerceUi(this);LinearLayout root=ui.col();root.setBackgroundColor(ui.bg);root.addView(header());ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout page=ui.col();page.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),ui.dp(24));scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setBody(root);
  page.addView(new CoinBalanceCard(this,w,false,hidden,()->{hidden=!hidden;draw(wallet);}));
  LinearLayout shortcuts=ui.row();shortcuts.setGravity(Gravity.TOP);int raw48=ui.dpRaw(48);String[][] actions={{"plus","Nạp xu"},{"arrow_up_right","Rút tiền"},{"store","Cửa hàng"}};for(int n=0;n<actions.length;n++){final int index=n;LinearLayout cell=ui.col();cell.setGravity(Gravity.CENTER);cell.setPadding(ui.dp(4),ui.dp(10),ui.dp(4),ui.dp(8));FrameLayout scBtn=ui.icon(actions[n][0],actions[n][1],()->{if(index==2)ui.go(StoreActivity.class);else if(index==0)topUp();else ui.moneyUnavailable("Rút tiền");});cell.addView(scBtn,new LinearLayout.LayoutParams(raw48,raw48));UiMetrics.enforceMinTouchTarget(scBtn);TextView t=ui.text(actions[n][1],11,ui.ink,true);t.setGravity(Gravity.CENTER);t.setPadding(0,ui.dp(7),0,0);cell.addView(t);shortcuts.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}page.addView(shortcuts);
  LinearLayout stats=ui.row();stats.setBaselineAligned(false);
  LinearLayout income=compactCard();income.addView(ui.text("Tiền có thể rút",11,ui.mutedStrict,false));TextView earned=ui.text(hidden?"••••":number(w.optLong("withdrawableVnd",w.optLong("earningsVnd")))+ "đ",20,ui.ink,true);earned.setSingleLine(true);earned.setTag("wallet:earnings");earned.setPadding(0,ui.dp(6),0,ui.dp(2));income.addView(earned);income.addView(ui.text(I18n.t("Chưa mở"),10,ui.mutedStrict,false));LinearLayout.LayoutParams ilp=new LinearLayout.LayoutParams(0,-2,1);ilp.rightMargin=ui.dp(4);stats.addView(income,ilp);
  LinearLayout trialGifts=compactCard();trialGifts.addView(ui.text("Quà từ xu tặng",11,ui.mutedStrict,false));TextView giftAmount=ui.text(hidden?"••••":number(w.optLong("giftedGiftValueCoins"))+" "+I18n.t("xu"),20,ui.ink,true);giftAmount.setSingleLine(true);giftAmount.setPadding(0,ui.dp(6),0,ui.dp(2));trialGifts.addView(giftAmount);trialGifts.addView(ui.text(I18n.t("Không rút"),10,ui.mutedStrict,false));LinearLayout.LayoutParams tlp=new LinearLayout.LayoutParams(0,-2,1);tlp.leftMargin=ui.dp(4);stats.addView(trialGifts,tlp);ui.add(page,stats,8);
  TextView history=ui.text("Giao dịch",15,ui.ink,true);history.setPadding(ui.dp(2),ui.dp(16),0,ui.dp(8));page.addView(history);
  HorizontalScrollView filterStrip=new HorizontalScrollView(this);filterStrip.setHorizontalScrollBarEnabled(false);LinearLayout filters=ui.row();filters.setPadding(0,0,0,ui.dp(10));String[][] cats={{"all","Tất cả"},{"spend","Chi tiêu"},{"grant","Nhận xu"},{"topup","Nạp xu"},{"income","Thu nhập"}};for(String[] cat:cats){final String key=cat[0];boolean active=key.equals(filter);Button chip=ui.action(cat[1],null,()->{filter=key;draw(wallet);});chip.setTag("wallet:filter:"+key);chip.setTextSize(12);chip.setMinLines(1);chip.setMinHeight(raw48);chip.setMinimumHeight(raw48);chip.setMinWidth(raw48);chip.setMinimumWidth(raw48);chip.setGravity(Gravity.CENTER);chip.setPadding(ui.dp(14),ui.dp(6),ui.dp(14),ui.dp(6));chip.setTextColor(active?Color.WHITE:ui.purpleText);chip.setBackground(ui.round(active?ui.purple:ui.soft,99));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.rightMargin=ui.dp(6);filters.addView(chip,lp);UiMetrics.enforceMinTouchTarget(chip);}filterStrip.addView(filters);page.addView(filterStrip);
  JSONArray entries=w.optJSONArray("entries");LinearLayout list=compactCard();list.setPadding(ui.dp(14),ui.dp(4),ui.dp(14),ui.dp(4));list.setTag("wallet:history");int shown=0;if(entries!=null)for(int n=0;n<entries.length();n++){JSONObject entry=entries.optJSONObject(n);if(entry==null)continue;String cat=entryCategory(entry);if(!filter.equals("all")&&!filter.equals(cat))continue;shown++;LinearLayout row=ui.row();row.setPadding(0,ui.dp(8),0,ui.dp(8));row.setMinimumHeight(raw48);String kind=entry.optString("kind");ImageView glyph=new ImageView(this);glyph.setImageDrawable(ui.glyph(entryIcon(kind),ui.purpleText,22));row.addView(glyph,new LinearLayout.LayoutParams(ui.dp(32),ui.dp(36)));LinearLayout copy=ui.col();copy.setPadding(ui.dp(8),0,ui.dp(6),0);boolean paidCoins=kind.equals("store_paid")||kind.equals("coin_purchase")||kind.equals("live_gift_paid");boolean trial=kind.equals("signup_trial")||kind.equals("live_gift_trial")||kind.equals("live_gift_received_trial")||kind.equals("store_trial")||kind.equals("admin_trial")||kind.equals("farm_trial");String defaultTitle=kind.equals("signup_trial")?"Xu chào mừng":(kind.equals("store_trial")||kind.equals("store_paid"))?"Gói cửa hàng":kind.equals("admin_trial")?"Xu được tặng":kind.equals("farm_trial")?(entry.optLong("coins")>=0?"Thu hoạch nông trại":"Mua vật phẩm nông trại"):kind.equals("live_gift_received_trial")?"Nhận quà Live":"Quà Live";String customTitle=entry.optString("title");copy.addView(ui.text(customTitle.isEmpty()?defaultTitle:customTitle,13,ui.ink,true));String date=new java.text.SimpleDateFormat("dd/MM · HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(entry.optLong("created")));String sub=entry.optString("subtitle");copy.addView(ui.text(sub.isEmpty()?date:date+" · "+I18n.t(sub),11,ui.mutedStrict,false));row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));final long entryAmount=entry.optLong(trial||paidCoins?"coins":"creatorVnd");final String amountStr=(entryAmount>0?"+":"")+number(entryAmount)+(trial||paidCoins?" "+I18n.t("xu"):"đ");TextView amount=ui.text(hidden?"••••":amountStr,14,ui.purpleText,true);amount.setGravity(Gravity.END);LinearLayout.LayoutParams amp=new LinearLayout.LayoutParams(-2,-2);amp.leftMargin=ui.dp(8);row.addView(amount,amp);final String detailTitle=customTitle.isEmpty()?I18n.t(defaultTitle):customTitle;row.setOnClickListener(v->new Sheet(this).setTitle(I18n.t("Chi tiết giao dịch")).setMessage(detailTitle+"\n"+I18n.t(trial?"Xu tặng":paidCoins?"Xu mua":"Thu nhập từ quà xu mua")+" · "+amountStr+"\n"+date+"\n\n"+I18n.t(trial?"Xu tặng không quy đổi thành tiền.":"Tỷ lệ chia áp dụng sau phí thanh toán và hoàn tiền.")).setPositiveButton(I18n.t("Đóng"),null).show());list.addView(row);UiMetrics.enforceMinTouchTarget(row);}if(shown==0)list.addView(ui.empty("gift","Chưa có giao dịch"));page.addView(list);
 }
 private void topUp(){LinearLayout body=ui.col();body.addView(ui.badge("1 "+I18n.t("xu")+" = "+number(wallet.optLong("vndPerCoin",100))+"đ"));JSONArray packs=wallet.optJSONArray("coinPacks");final Button unavailable=ui.action("Chưa mở nạp",null,()->{});unavailable.setEnabled(false);unavailable.setBackground(ui.round(ui.soft,99));unavailable.setTextColor(ui.mutedStrict);LinearLayout row=null;for(int i=0;packs!=null&&i<packs.length();i++){JSONObject pack=packs.optJSONObject(i);if(pack==null)continue;if(i%2==0){row=ui.row();body.addView(row);}LinearLayout option=ui.section();TextView coins=ui.text(number(pack.optLong("coins"))+" "+I18n.t("xu"),17,ui.purpleText,true);coins.setGravity(Gravity.CENTER);option.addView(coins);TextView price=ui.text(number(pack.optLong("referenceVnd"))+"đ",13,ui.mutedStrict,false);price.setGravity(Gravity.CENTER);option.addView(price);option.setContentDescription(coins.getText()+" · "+price.getText());option.setOnClickListener(v->{for(int n=0;n<body.getChildCount();n++){View child=body.getChildAt(n);if(child instanceof LinearLayout)for(int k=0;k<((LinearLayout)child).getChildCount();k++){View c=((LinearLayout)child).getChildAt(k);if(c instanceof LinearLayout)c.setBackground(ui.round(ui.card,20));}}option.setBackground(ui.round(ui.soft,20));});LinearLayout.LayoutParams slot=new LinearLayout.LayoutParams(0,-2,1);slot.setMargins(ui.dp(4),ui.dp(6),ui.dp(4),ui.dp(6));row.addView(option,slot);UiMetrics.enforceMinTouchTarget(option);}if(packs==null||packs.length()==0)body.addView(ui.empty("wallet","Chưa có gói nạp"));TextView note=ui.text("Đang kết nối thanh toán",12,ui.mutedStrict,false);note.setGravity(Gravity.CENTER);ui.add(body,note,12);ui.add(body,unavailable,10);UiMetrics.enforceMinTouchTarget(unavailable);ScrollView scroller=new ScrollView(this){protected void onMeasure(int w,int h){super.onMeasure(w,View.MeasureSpec.makeMeasureSpec(getResources().getDisplayMetrics().heightPixels*65/100,View.MeasureSpec.AT_MOST));}};scroller.addView(body);new Sheet(this).setTitle(I18n.t("Nạp xu")).setView(scroller).show();
 }

}
